changeSet.sql:
ALTER TABLE document.contracts ADD COLUMN IF NOT EXISTS creator_in TEXT;

-- Mavjud created_by_user_id (UUID) larni PINFL/STIR'ga backfill (cross-schema).
UPDATE document.contracts c
   SET creator_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = c.created_by_user_id)
 WHERE c.creator_in IS NULL AND c.created_by_user_id IS NOT NULL;

ALTER TABLE document.contracts DROP COLUMN IF EXISTS created_by_user_id;
